using UnityEngine;
using UnityEditor;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("project=" + Application.dataPath + " unity=" + Application.unityVersion + " playing=" + EditorApplication.isPlaying + " compiling=" + EditorApplication.isCompiling + " compileFailed=" + EditorUtility.scriptCompilationFailed);
            foreach (var guid in AssetDatabase.FindAssets("t:Model"))
            {
                var p = AssetDatabase.GUIDToAssetPath(guid);
                if (!p.StartsWith("Assets/"))
                    continue;
                var assets = AssetDatabase.LoadAllAssetsAtPath(p);
                int clips = 0;
                foreach (var a in assets)
                    if (a is AnimationClip c && !c.name.StartsWith("__preview__"))
                    {
                        clips++;
                        result.Log("CLIP " + p + " " + c.name + " duration=" + c.length + " loop=" + c.isLooping);
                    }

                result.Log("MODEL " + p + " clips=" + clips);
            }

            foreach (var s in EditorBuildSettings.scenes)
                result.Log("BUILD " + s.path + " enabled=" + s.enabled + " exists=" + System.IO.File.Exists(s.path));
            result.Log("SCENE " + UnityEngine.SceneManagement.SceneManager.GetActiveScene().path);
        }
    }
}
